"use client";
import { useState } from "react";

const projects = [
  {
    title: "Race Telemetry Dashboard",
    description: "Real-time telemetry analysis platform",
    tags: ["FastAPI", "React", "Python"],
    category: "Data",
  },
  {
    title: "Strategy Simulator",
    description: "Race strategy simulation tool",
    tags: ["Python", "NumPy"],
    category: "Simulation",
  },
  {
    title: "Telemetry API",
    description: "Backend service for processing telemetry",
    tags: ["FastAPI", "Docker", "PostgreSQL"],
    category: "Backend",
  },
];

export default function ProjectsPage() {
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");

  const filtered = projects.filter((p) => {
    const matchesSearch =
      (p.title + p.description + p.tags.join(" "))
        .toLowerCase()
        .includes(search.toLowerCase());

    const matchesCategory =
      category === "All" || p.category === category;

    return matchesSearch && matchesCategory;
  });

  return (
    <main
      style={{
        padding: "120px 60px",
        color: "white",
      }}
    >
      <h1 style={{ fontSize: "40px", marginBottom: "10px" }}>
        Projects
      </h1>

      <p style={{ opacity: 0.7, marginBottom: "30px" }}>
        A collection of software projects focused on data, telemetry
        analysis and performance engineering.
      </p>

      {/* 🔍 SEARCH */}
      <input
        placeholder="Search projects..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{
          padding: "12px",
          width: "300px",
          borderRadius: "8px",
          border: "1px solid #334155",
          background: "#020617",
          color: "white",
          marginBottom: "20px",
        }}
      />

      {/* 🏷️ FILTERS */}
      <div style={{ display: "flex", gap: "10px", marginBottom: "30px" }}>
        {["All", "Data", "Backend", "Simulation"].map((c) => (
          <button
            key={c}
            onClick={() => setCategory(c)}
            style={{
              padding: "6px 14px",
              borderRadius: "20px",
              border: "1px solid #334155",
              background: category === c ? "#e11d48" : "transparent",
              color: "white",
              cursor: "pointer",
            }}
          >
            {c}
          </button>
        ))}
      </div>

      {/* 🧩 PROJECT GRID */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
          gap: "20px",
        }}
      >
        {filtered.map((p) => (
          <div
            key={p.title}
            style={{
              padding: "20px",
              borderRadius: "12px",
              border: "1px solid #1e293b",
              background: "#020617",
            }}
          >
            <h3 style={{ marginBottom: "10px" }}>{p.title}</h3>

            <p style={{ opacity: 0.6, fontSize: "14px" }}>
              {p.description}
            </p>

            {/* TAGS */}
            <div
              style={{
                marginTop: "15px",
                display: "flex",
                gap: "8px",
                flexWrap: "wrap",
              }}
            >
              {p.tags.map((tag) => (
                <span
                  key={tag}
                  onClick={() => setSearch(tag)}
                  style={{
                    fontSize: "12px",
                    padding: "4px 10px",
                    borderRadius: "999px",
                    background: "#1e293b",
                    cursor: "pointer",
                  }}
                >
                  {tag}
                </span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </main>
  );
}